import { DsCheckbox } from './checkbox';
const meta = {
    title: 'Components/Checkbox',
    component: DsCheckbox,
    tags: ['autodocs'],
    args: { label: 'Accept terms and conditions', description: undefined, checked: false, disabled: false, invalid: false },
};
export default meta;
export const Default = {};
export const Checked = { args: { checked: true } };
export const WithDescription = { args: { description: 'You agree to our Terms of Service and Privacy Policy.' } };
export const Invalid = { args: { invalid: true } };
export const Disabled = { args: { disabled: true } };
